// اجرای تابع فقط بعد از توقف رویدادها
function debounce(fn, wait = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
}

const onSearch = debounce((q) => console.log("search:", q), 400);
onSearch("portfolio");

